using Bench.Domain;
using FluentAssertions;
using ModelArms.Core.Experiment;
using ModelArms.Core.Launch;
using ModelArms.Core.Steps;
using Xunit;

namespace Bench.Tests.ModelArms;

/// <summary>What a done step must have left, over its BINDINGS and never a kind table (plan D21, D25; E2 §8 items 2 and 3): the verdict file a review's last result is written to, the
/// <c>.diff</c> of the step a <c>diffFrom</c> names, the task coder's head and diff. A missing output whose inputs exist is regenerated by the one function the first run used; a missing
/// INPUT leaves the step resumable, never done with a hole. The steps are the worked example's own (<c>part6.experiment.json</c>), read through the real reader.
/// <para>
/// What this does NOT prove: that the runner writes the regenerated bytes equal to the first run's (E2.S4's restart scenario compares them), or that a <c>.before</c> this function is told
/// exists really holds the right commit.
/// </para></summary>
public sealed class StepOutputsTests
{
    private static StepSpec Step(string id) => BriefExample.Experiment.Steps[new StepId(id)];

    private static Outcome<ClaudeResultEnvelope> Result(string fixture) => ClaudeResultEnvelope.LastOf(ModelArmsFixtures.Read(fixture));

    private static OutputFacts Facts(
        IEnumerable<DerivedOutput>? present = null,
        bool before = false,
        bool taskBefore = false,
        Outcome<ClaudeResultEnvelope>? final = null) =>
        new(new HashSet<DerivedOutput>(present ?? []), before, taskBefore, final ?? Outcome<ClaudeResultEnvelope>.Failure("no result line"));

    [Fact]
    public void A_review_step_with_a_result_and_no_verdict_file_is_regenerated()
    {
        foreach (var id in new[] { "review", "hA", "hB" })
        {
            StepOutputs.Reconcile(Step(id), Facts(final: Result("result-success.jsonl"))).Should().Be(
                new OutputAnswer.Regenerate([DerivedOutput.Verdict]), $"{id} binds a verdict, so a result with no verdict file is regenerated — C's review.json and CHH's hA.json are one rule");
        }
    }

    [Theory]
    [InlineData("hreview")]
    [InlineData("gate")]
    [InlineData("hfix")]
    public void A_snapshotting_step_with_a_before_and_no_diff_is_regenerated_from_the_named_snapshot(string id)
    {
        StepOutputs.Reconcile(Step(id), Facts(before: true)).Should().Be(
            new OutputAnswer.Regenerate([DerivedOutput.StepDiff]), "hreview and gate name their own snapshot, hfix names hA's: the diff is regenerated from the one the binding names");
    }

    [Fact]
    public void A_derived_output_whose_input_is_missing_leaves_the_step_resumable_naming_the_input()
    {
        StepOutputs.Reconcile(Step("hreview"), Facts(before: false)).Should().BeOfType<OutputAnswer.Resumable>().Which.Reason.Should().Contain(".before is missing");
        StepOutputs.Reconcile(Step("hfix"), Facts(before: false)).Should().BeOfType<OutputAnswer.Resumable>().Which.Reason.Should().Contain("hA.before is missing", "the snapshot is the NAMED step's");
        StepOutputs.Reconcile(Step("review"), Facts(final: Result("result-400-model-unsupported.jsonl"))).Should().BeOfType<OutputAnswer.Resumable>().Which.Reason.Should().Contain("no result text");
        StepOutputs.Reconcile(Step("review"), Facts(final: Outcome<ClaudeResultEnvelope>.Failure("no result line"))).Should().BeOfType<OutputAnswer.Resumable>().Which.Reason.Should().Contain("no result text");
        StepOutputs.Reconcile(Step("review"), Facts(final: Outcome<ClaudeResultEnvelope>.Success(new ClaudeResultEnvelope(false, Bench.Domain.Trace.CapturedCount.Unavailable("absent"), string.Empty, "  \n", [], "success", 3))))
            .Should().BeOfType<OutputAnswer.Resumable>().Which.Reason.Should().Contain("no result text", "a result of blank text has no verdict to read either");
        StepOutputs.Reconcile(Step("taskCode"), Facts(taskBefore: false)).Should().BeOfType<OutputAnswer.Resumable>().Which.Reason.Should().Contain("before is missing");

        StepOutputs.Reconcile(Step("review"), Facts(final: Result("result-success.jsonl"))).Should().BeOfType<OutputAnswer.Regenerate>("the positive companion: the same facts with a result are no refusal");
    }

    public static TheoryData<string, DerivedOutput[]> Complete => new()
    {
        { "code", [] },
        { "splitFix", [] },
        { "review", [DerivedOutput.Verdict] },
        { "gate", [DerivedOutput.StepDiff] },
        { "taskCode", [DerivedOutput.CoderHead, DerivedOutput.CoderDiff] },
    };

    /// <summary>The red of this scenario is a plant: make <c>Of</c> answer <c>[StepDiff]</c> for a step with no binding and a step that needs nothing reads as one with a hole.</summary>
    [Theory]
    [MemberData(nameof(Complete))]
    public void A_complete_step_needs_nothing(string id, DerivedOutput[] present)
    {
        StepOutputs.Reconcile(Step(id), Facts(present, before: false, taskBefore: false)).Should().BeOfType<OutputAnswer.Complete>(
            "every output this step's bindings name is present — a step without bindings needs nothing and no input is looked at");
    }

    [Fact]
    public void A_steps_derived_outputs_follow_from_its_bindings_alone()
    {
        foreach (var kind in Enum.GetValues<StepKind>())
        {
            var specs = BriefExample.Experiment.Steps.Values.Where(spec => spec.Kind == kind).ToList();
            specs.Should().NotBeEmpty($"the example places a {kind} step — a kind with no step would leave its rule unproven");
        }

        StepOutputs.Of(Step("code")).Should().BeEmpty();
        StepOutputs.Of(Step("fix")).Should().BeEmpty();
        StepOutputs.Of(Step("split")).Should().BeEmpty();
        StepOutputs.Of(Step("splitFix")).Should().BeEmpty();
        StepOutputs.Of(Step("review")).Should().Equal(DerivedOutput.Verdict);
        StepOutputs.Of(Step("gate")).Should().Equal(DerivedOutput.StepDiff);
        StepOutputs.Of(Step("hfix")).Should().Equal(DerivedOutput.StepDiff);
        StepOutputs.Of(Step("taskCode")).Should().Equal(DerivedOutput.CoderHead, DerivedOutput.CoderDiff);
        StepOutputs.Of(Step("review") with { DiffFrom = "review" }).Should().Equal(DerivedOutput.Verdict, DerivedOutput.StepDiff);
        StepOutputs.NeedsBefore(Step("hreview")).Should().BeTrue();
        StepOutputs.NeedsBefore(Step("hfix")).Should().BeFalse("hfix takes no snapshot of its own — its diff spans from hA's");
    }

    [Fact]
    public void Regeneration_is_the_same_function_the_first_run_used()
    {
        var firstRun = Facts(final: Result("result-success.jsonl"));
        var reEntry = Facts(final: Result("result-success.jsonl"), before: true, taskBefore: true);

        StepOutputs.Reconcile(Step("review"), firstRun).Should().Be(StepOutputs.Reconcile(Step("review"), reEntry), "the two differ only in history the type cannot see");
        StepOutputs.Reconcile(Step("review"), firstRun).Should().Be(new OutputAnswer.Regenerate([DerivedOutput.Verdict]));
        StepOutputs.Reconcile(Step("hreview"), Facts(before: true)).Should().Be(StepOutputs.Reconcile(Step("hreview"), Facts(before: true, final: Result("result-success.jsonl"))));
    }

    [Fact]
    public void A_review_that_ended_on_its_deadline_without_a_result_is_resumable_not_done_with_a_hole()
    {
        StepOutputs.Reconcile(Step("review"), Facts(final: Outcome<ClaudeResultEnvelope>.Failure("no result line"))).Should().BeOfType<OutputAnswer.Resumable>(
            "a review killed at its wall before its result has no verdict to read — the plan's D21 wins over D8 for this one case");
    }
}
